    css: `/* ===================== 气泡呼吸与装饰（❄玻璃蓝） ===================== */

/* 通用气泡样式 */
.message-sent,
.message-received {
position: relative;
background: linear-gradient(135deg,
rgba(219, 234, 254, 0.7),
rgba(191, 219, 254, 0.6)
) !important;
box-shadow: 0 10px 26px rgba(15, 23, 42, 0.10) !important;
border: 1px solid rgba(37, 99, 235, 0.20) !important;
border-top: 1px solid rgba(255, 255, 255, 0.55) !important;
border-left: 1px solid rgba(255, 255, 255, 0.45) !important;
color: #0f172a !important;
backdrop-filter: blur(8px) saturate(110%);
-webkit-backdrop-filter: blur(8px) saturate(110%);
overflow: visible;
transition: all 0.35s cubic-bezier(0.2, 0.9, 0.4, 1.1);
}

/* 我方气泡（浅蓝） */
.message-sent {
background: linear-gradient(135deg,
rgba(191, 219, 254, 0.7),
rgba(147, 197, 253, 0.5)
) !important;
border-radius: 20px 20px 6px 20px;
}

/* 对方气泡（饱和度更高） */
.message-received {
background: linear-gradient(135deg,
rgba(179, 215, 255, 0.75),
rgba(120, 180, 250, 0.65)
) !important;
border-radius: 20px 20px 20px 6px;
}

/* ===================== 悬浮弹动 ===================== */
@keyframes jellyFloat {
0% { transform: translateY(0) scale(1); }
50% { transform: translateY(-5px) scale(1.015); }
100% { transform: translateY(0) scale(1); }
}
.message-sent:hover,
.message-received:hover {
animation: jellyFloat 0.6s ease-in-out;
}

/* ===================== 呼吸变色动画（蓝调） ===================== */
@keyframes breatheBlue {
0% {
color: #b3d9ff;
text-shadow: 0 0 6px #a0d0ff, 0 0 3px rgba(150, 200, 255, 0.5);
}
50% {
color: #80c0ff;
text-shadow: 0 0 12px #6ab0ff, 0 0 6px rgba(100, 180, 255, 0.6);
}
100% {
color: #b3d9ff;
text-shadow: 0 0 6px #a0d0ff, 0 0 3px rgba(150, 200, 255, 0.5);
}
}
@keyframes breatheDeepBlue {
0% {
color: #8fc0ff;
text-shadow: 0 0 8px #70a8ff, 0 0 4px rgba(100, 150, 230, 0.5);
}
50% {
color: #6098ff;
text-shadow: 0 0 14px #5088ff, 0 0 7px rgba(80, 120, 220, 0.6);
}
100% {
color: #8fc0ff;
text-shadow: 0 0 8px #70a8ff, 0 0 4px rgba(100, 150, 230, 0.5);
}
}

/* 雪花飘移 */
@keyframes snowDrift {
0% { transform: translate(0, 0); }
50% { transform: translate(4px, -3px); }
100% { transform: translate(0, 0); }
}

/* ===================== 装饰雪花 ❄ ===================== */

/* 对方气泡左上角大雪花 */
.message-received::before {
content: '❄';
position: absolute;
font-size: 22px;
top: -14px;
left: -22px;
font-weight: bold;
pointer-events: none;
z-index: 99;
white-space: nowrap;
animation: breatheBlue 3s ease-in-out infinite, snowDrift 4s ease-in-out infinite;
}

/* 对方气泡左下角小雪花 */
.message-received::after {
content: '❄';
position: absolute;
font-size: 16px;
bottom: -12px;
left: -10px;
font-weight: bold;
pointer-events: none;
z-index: 99;
animation: breatheDeepBlue 2.8s ease-in-out infinite, snowDrift 3.5s ease-in-out infinite;
}

/* 我方气泡右上角大雪花 */
.message-sent::before {
content: '❄';
position: absolute;
font-size: 22px;
top: -14px;
right: -22px;
font-weight: bold;
pointer-events: none;
z-index: 99;
white-space: nowrap;
animation: breatheBlue 3s ease-in-out infinite, snowDrift 4s ease-in-out infinite;
}

/* 我方气泡右下角小雪花 */
.message-sent::after {
content: '❄';
position: absolute;
font-size: 16px;
bottom: -12px;
right: -10px;
font-weight: bold;
pointer-events: none;
z-index: 99;
animation: breatheDeepBlue 2.8s ease-in-out infinite, snowDrift 3.5s ease-in-out infinite;
}`
